import java.util.*;

class Solution {
  public int getMaxRepetitions(String s1, int n1, String s2, int n2) {
    // after each copy of s1, record (position in s2, completed s2 count); a repeated position means a cycle
    Map<Integer, int[]> seen = new HashMap<>(); // s2 index -> {s1 copies used, s2 copies completed}
    int index = 0, count = 0;
    for (int k = 1; k <= n1; k++) {
      for (char c : s1.toCharArray()) {
        if (c == s2.charAt(index) && ++index == s2.length()) {
          index = 0;
          count++;
        }
      }
      int[] prev = seen.get(index);
      if (prev != null) {
        int cycleLen = k - prev[0], cycleCount = count - prev[1];
        int cycles = (n1 - k) / cycleLen;
        count += cycles * cycleCount;
        k += cycles * cycleLen;
        // finish the leftover copies directly
        for (; k < n1; k++) {
          for (char c : s1.toCharArray()) {
            if (c == s2.charAt(index) && ++index == s2.length()) {
              index = 0;
              count++;
            }
          }
        }
        break;
      }
      seen.put(index, new int[] {k, count});
    }
    return count / n2;
  }
}
